const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "// prisma/schema.prisma\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ==================== Organización ====================\nmodel School {\n  id               String            @id @default(cuid())\n  name             String\n  branches         Branch[]\n  users            User[]\n  students         Student[]\n  enrollments      Enrollment[]\n  beltRanks        BeltRank[]\n  techniques       Technique[]\n  achievementTypes AchievementType[]\n  createdAt        DateTime          @default(now())\n  updatedAt        DateTime          @updatedAt\n}\n\nmodel Branch {\n  id          String       @id @default(cuid())\n  name        String\n  schoolId    String\n  school      School       @relation(fields: [schoolId], references: [id])\n  users       User[]\n  students    Student[]\n  enrollments Enrollment[]\n  classes     Class[]\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n}\n\n// ==================== Usuarios y roles ====================\nenum Role {\n  STUDENT\n  GUARDIAN\n  INSTRUCTOR\n  SCHOOL_ADMIN\n  SUPERADMIN\n}\n\nmodel User {\n  id                      String                   @id @default(cuid())\n  email                   String                   @unique\n  emailVerified           DateTime?\n  passwordHash            String?\n  name                    String?\n  phone                   String?\n  role                    Role                     @default(STUDENT) // rol principal (compatibilidad)\n  roles                   Role[]                   @default([]) // todos los roles del usuario (multirol)\n  schoolId                String?\n  school                  School?                  @relation(fields: [schoolId], references: [id])\n  branchId                String?\n  branch                  Branch?                  @relation(fields: [branchId], references: [id])\n  instructorProfile       InstructorProfile?\n  studentProfile          Student?\n  guardians               GuardianStudent[]        @relation(\"guardian\")\n  guardianOfStudents      Student[]                @relation(\"primaryGuardian\")\n  rankPromotions          StudentRankHistory[]     @relation(\"rankPromoter\")\n  techniqueEvaluations    TechniqueEvaluation[]    @relation(\"techniqueEvaluator\")\n  attendanceConfirmations Attendance[]             @relation(\"attendanceConfirmer\")\n  emailVerificationTokens EmailVerificationToken[]\n  passwordResetTokens     PasswordResetToken[]\n  acceptedInvitations     StudentInvitationToken[]\n  classes                 Class[]                  @relation(\"instructor\")\n  createdAt               DateTime                 @default(now())\n  updatedAt               DateTime                 @updatedAt\n}\n\nmodel EmailVerificationToken {\n  id        String    @id @default(cuid())\n  token     String    @unique // hash del token\n  userId    String\n  user      User      @relation(fields: [userId], references: [id])\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n}\n\nmodel PasswordResetToken {\n  id        String    @id @default(cuid())\n  token     String    @unique // hash del token\n  userId    String\n  user      User      @relation(fields: [userId], references: [id])\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n}\n\nmodel StudentInvitationToken {\n  id           String    @id @default(cuid())\n  token        String    @unique // hash del token\n  studentId    String\n  student      Student   @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  email        String // correo destino de la invitación\n  expiresAt    DateTime\n  usedAt       DateTime?\n  usedByUserId String? // id del User que aceptó la invitación\n  usedBy       User?     @relation(fields: [usedByUserId], references: [id])\n  createdAt    DateTime  @default(now())\n\n  @@index([studentId])\n  @@index([expiresAt])\n}\n\nmodel InstructorProfile {\n  id          String   @id @default(cuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id])\n  bio         String?\n  specialties String[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel Student {\n  id                  String                   @id @default(cuid())\n  userId              String?                  @unique // si el estudiante tiene cuenta propia (mayor de edad)\n  guardianId          String? // referencia al User tutor (si es menor)\n  schoolId            String\n  branchId            String\n  firstName           String\n  lastName            String\n  dateOfBirth         DateTime\n  email               String? // correo de contacto para la invitación de acceso\n  contactPhone        String?\n  medicalInfo         String?\n  emergencyContact    String?\n  enrollmentDate      DateTime                 @default(now())\n  memberNumber        String?                  @unique // matrícula KYU-YYYY-NNN\n  status              String                   @default(\"ACTIVE\") // ACTIVE, INACTIVE, GRADUATED\n  currentRank         String?\n  photoKey            String? // clave en Supabase Storage\n  registrationData    Json?\n  school              School                   @relation(fields: [schoolId], references: [id])\n  branch              Branch                   @relation(fields: [branchId], references: [id])\n  user                User?                    @relation(fields: [userId], references: [id])\n  guardian            User?                    @relation(\"primaryGuardian\", fields: [guardianId], references: [id])\n  guardians           GuardianStudent[]        @relation(\"student\")\n  enrollments         Enrollment[]\n  attendances         Attendance[]\n  achievements        StudentAchievement[]\n  techniques          StudentTechnique[]\n  fitnessReports      FitnessReport[]\n  classEnrollments    ClassEnrollment[]\n  rankHistory         StudentRankHistory[]\n  enrollmentApplicant EnrollmentApplicant?\n  invitationTokens    StudentInvitationToken[]\n  documents           StudentDocument[]\n  createdAt           DateTime                 @default(now())\n  updatedAt           DateTime                 @updatedAt\n}\n\n// Relación muchos a muchos entre tutores y estudiantes\nmodel GuardianStudent {\n  guardianId   String\n  studentId    String\n  guardian     User     @relation(\"guardian\", fields: [guardianId], references: [id])\n  student      Student  @relation(\"student\", fields: [studentId], references: [id])\n  relationship String? // padre, madre, tutor legal...\n  createdAt    DateTime @default(now())\n\n  @@id([guardianId, studentId])\n}\n\n// ==================== Inscripciones ====================\nenum EnrollmentOrigin {\n  FORM\n  ASSISTANT\n}\n\nenum StudentDocumentType {\n  PROFILE_PHOTO\n  IDENTITY\n  BIRTH_CERTIFICATE\n  PASSPORT\n  MEDICAL_CERTIFICATE\n  OTHER\n}\n\nenum StudentDocumentStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  EXPIRED\n}\n\nenum TechniqueCategory {\n  KIHON\n  KATA\n  KUMITE\n  BUNKAI\n}\n\nmodel Enrollment {\n  id               String                @id @default(cuid())\n  origin           EnrollmentOrigin\n  schoolId         String?\n  school           School?               @relation(fields: [schoolId], references: [id])\n  branchId         String?\n  branch           Branch?               @relation(fields: [branchId], references: [id])\n  applicantName    String?\n  interest         String? // qué le interesa (karate, defensa personal...)\n  schedule         String? // horario preferido\n  quote            String? // cotización dada\n  studentId        String? // si ya se creó el expediente\n  student          Student?              @relation(fields: [studentId], references: [id])\n  contactEmail     String\n  contactPhone     String?\n  status           String                @default(\"PENDING\") // PENDING, CONTACTED, ENROLLED, REJECTED\n  notes            String?\n  registrationData Json?\n  applicants       EnrollmentApplicant[]\n  documents        StudentDocument[]\n  createdAt        DateTime              @default(now())\n  updatedAt        DateTime              @updatedAt\n\n  @@unique([contactEmail, status]) // control básico de duplicados\n}\n\nmodel EnrollmentApplicant {\n  id           String            @id @default(cuid())\n  enrollmentId String\n  studentId    String?           @unique\n  name         String\n  dateOfBirth  DateTime\n  profileData  Json\n  enrollment   Enrollment        @relation(fields: [enrollmentId], references: [id], onDelete: Cascade)\n  student      Student?          @relation(fields: [studentId], references: [id])\n  documents    StudentDocument[]\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n\n  @@index([enrollmentId])\n}\n\nmodel StudentDocument {\n  id           String                @id @default(cuid())\n  enrollmentId String\n  applicantId  String?\n  studentId    String?\n  type         StudentDocumentType\n  status       StudentDocumentStatus @default(PENDING)\n  fileName     String\n  storageKey   String                @unique\n  mimeType     String\n  fileSize     Int\n  reviewNotes  String?\n  reviewedAt   DateTime?\n  enrollment   Enrollment            @relation(fields: [enrollmentId], references: [id], onDelete: Cascade)\n  applicant    EnrollmentApplicant?  @relation(fields: [applicantId], references: [id], onDelete: SetNull)\n  student      Student?              @relation(fields: [studentId], references: [id], onDelete: SetNull)\n  uploadedAt   DateTime              @default(now())\n  updatedAt    DateTime              @updatedAt\n\n  @@index([applicantId])\n  @@index([studentId, status])\n}\n\n// ==================== Rangos y técnicas ====================\nenum Program {\n  ADULT // 18+\n  YOUTH // 11-17\n}\n\nmodel BeltRank {\n  id                      String               @id @default(cuid())\n  program                 Program              @default(ADULT)\n  name                    String // Blanco, Amarillo, etc.\n  kyuDan                  String? // e.g. \"10TH KYU\", \"SHODAN\"\n  japaneseName            String? // e.g. \"Ju-kyu\", \"Shodan\"\n  kanji                   String? // e.g. \"十級\", \"初段\"\n  order                   Int // orden secuencial dentro del programa\n  beltColor               String? // color del cinturón (hex)\n  beltSecondaryColor      String? // color secundario (franjas)\n  isMaximumRank           Boolean              @default(false)\n  estimatedDurationMonths Int? // duración estimada del grado\n  description             String?\n  schoolId                String?\n  minMonths               Int? // permanencia mínima para examen\n  maxMonths               Int? // permanencia máxima estimada para el grado\n  minAttendancePercent    Int? // asistencia mínima exigida para examen\n  school                  School?              @relation(fields: [schoolId], references: [id])\n  katas                   BeltRankKata[]\n  techniques              Technique[]\n  promotions              StudentRankHistory[]\n  createdAt               DateTime             @default(now())\n  updatedAt               DateTime             @updatedAt\n\n  @@unique([program, order])\n}\n\n// Katas requeridas por grado (catálogo M:N). Reutiliza Technique con category KATA.\nmodel BeltRankKata {\n  beltRankId String\n  kataId     String\n  order      Int       @default(0) // posición dentro del grado\n  beltRank   BeltRank  @relation(fields: [beltRankId], references: [id], onDelete: Cascade)\n  kata       Technique @relation(fields: [kataId], references: [id], onDelete: Cascade)\n  createdAt  DateTime  @default(now())\n\n  @@id([beltRankId, kataId])\n  @@index([kataId])\n}\n\nmodel StudentRankHistory {\n  id           String   @id @default(cuid())\n  studentId    String\n  beltRankId   String\n  promotedBy   String?\n  promotedAt   DateTime @default(now())\n  examinerName String? // sensei sinodal / evaluador del examen\n  notes        String?\n  student      Student  @relation(fields: [studentId], references: [id])\n  beltRank     BeltRank @relation(fields: [beltRankId], references: [id])\n  promoter     User?    @relation(\"rankPromoter\", fields: [promotedBy], references: [id])\n  createdAt    DateTime @default(now())\n\n  @@index([studentId, promotedAt])\n  @@index([beltRankId])\n}\n\nmodel Technique {\n  id             String             @id @default(cuid())\n  name           String // nombre de la técnica (kata, kihon, etc.)\n  japaneseName   String?\n  kanji          String?\n  description    String?\n  category       TechniqueCategory  @default(KIHON)\n  rankId         String?\n  rank           BeltRank?          @relation(fields: [rankId], references: [id])\n  order          Int                @default(0) // orden pedagógico dentro del grado\n  movementsCount Int?\n  embusen        String? // patrón de desplazamiento (I, H, Cruz...)\n  difficulty     String? // Básica, Intermedia, Avanzada\n  videoUrl       String?\n  schoolId       String?\n  school         School?            @relation(fields: [schoolId], references: [id])\n  beltRankKatas  BeltRankKata[]\n  students       StudentTechnique[]\n  createdAt      DateTime           @default(now())\n  updatedAt      DateTime           @updatedAt\n}\n\nmodel StudentTechnique {\n  id               String               @id @default(cuid())\n  studentId        String\n  techniqueId      String\n  student          Student              @relation(fields: [studentId], references: [id])\n  technique        Technique            @relation(fields: [techniqueId], references: [id])\n  approved         Boolean              @default(false)\n  approvedBy       String?\n  approvedAt       DateTime?\n  inPractice       Boolean              @default(false)\n  practiceHours    Float                @default(0)\n  lastPracticeDate DateTime?\n  notes            String?\n  evaluation       TechniqueEvaluation?\n  createdAt        DateTime             @default(now())\n\n  @@unique([studentId, techniqueId])\n}\n\nmodel TechniqueEvaluation {\n  id                 String           @id @default(cuid())\n  studentTechniqueId String           @unique\n  score              Int\n  feedback           String?\n  evaluatedBy        String\n  evaluatedAt        DateTime         @default(now())\n  studentTechnique   StudentTechnique @relation(fields: [studentTechniqueId], references: [id], onDelete: Cascade)\n  evaluator          User             @relation(\"techniqueEvaluator\", fields: [evaluatedBy], references: [id])\n  createdAt          DateTime         @default(now())\n  updatedAt          DateTime         @updatedAt\n\n  @@index([evaluatedBy, evaluatedAt])\n}\n\n// ==================== Clases y asistencia ====================\nmodel Class {\n  id           String            @id @default(cuid())\n  name         String\n  description  String?\n  branchId     String\n  branch       Branch            @relation(fields: [branchId], references: [id])\n  instructorId String?\n  instructor   User?             @relation(\"instructor\", fields: [instructorId], references: [id])\n  dayOfWeek    Int // 0=domingo, 1=lunes...\n  startTime    String // formato \"HH:MM\"\n  endTime      String\n  sessions     ClassSession[]\n  enrollments  ClassEnrollment[]\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n}\n\nmodel ClassEnrollment {\n  id         String    @id @default(cuid())\n  classId    String\n  studentId  String\n  status     String    @default(\"ACTIVE\") // ACTIVE, PAUSED, COMPLETED\n  enrolledAt DateTime  @default(now())\n  endedAt    DateTime?\n  notes      String?\n  class      Class     @relation(fields: [classId], references: [id])\n  student    Student   @relation(fields: [studentId], references: [id])\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  @@unique([classId, studentId])\n  @@index([studentId, status])\n  @@index([classId, status])\n}\n\nmodel ClassSession {\n  id          String       @id @default(cuid())\n  classId     String\n  class       Class        @relation(fields: [classId], references: [id])\n  date        DateTime\n  notes       String?\n  attendances Attendance[]\n  createdAt   DateTime     @default(now())\n\n  @@unique([classId, date])\n}\n\nenum AttendanceStatus {\n  PENDING\n  CONFIRMED\n  REJECTED\n}\n\nmodel Attendance {\n  id            String           @id @default(cuid())\n  sessionId     String?\n  session       ClassSession?    @relation(fields: [sessionId], references: [id])\n  studentId     String\n  student       Student          @relation(fields: [studentId], references: [id])\n  date          DateTime         @default(now()) // fecha del registro (punch-in o pase de lista)\n  present       Boolean          @default(true)\n  hoursTrained  Float            @default(1)\n  sessionType   String?\n  status        AttendanceStatus @default(PENDING)\n  punchedAt     DateTime         @default(now())\n  confirmedAt   DateTime?\n  confirmedById String?\n  confirmedBy   User?            @relation(\"attendanceConfirmer\", fields: [confirmedById], references: [id])\n  notes         String?\n  createdAt     DateTime         @default(now())\n  updatedAt     DateTime         @updatedAt\n\n  @@unique([sessionId, studentId])\n  @@index([studentId, date])\n  @@index([status, date])\n}\n\n// ==================== Logros y reportes ====================\nmodel AchievementType {\n  id           String               @id @default(cuid())\n  name         String // \"Cinturón amarillo\", \"Torneo\", etc.\n  description  String?\n  schoolId     String?\n  school       School?              @relation(fields: [schoolId], references: [id])\n  achievements StudentAchievement[]\n  createdAt    DateTime             @default(now())\n}\n\nmodel StudentAchievement {\n  id          String          @id @default(cuid())\n  studentId   String\n  student     Student         @relation(fields: [studentId], references: [id])\n  typeId      String\n  type        AchievementType @relation(fields: [typeId], references: [id])\n  evidenceKey String? // clave en Storage\n  approvedBy  String?\n  comment     String?\n  status      String          @default(\"PENDING\") // PENDING, APPROVED, REJECTED\n  achievedAt  DateTime        @default(now())\n  createdAt   DateTime        @default(now())\n}\n\nmodel FitnessReport {\n  id          String   @id @default(cuid())\n  studentId   String\n  student     Student  @relation(fields: [studentId], references: [id])\n  report      String // texto del auto-reporte\n  evidenceKey String?\n  approvedBy  String?\n  comment     String?\n  status      String   @default(\"PENDING\")\n  createdAt   DateTime @default(now())\n}\n"
}

